// Componente de Verificación de Email

import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router } from '@angular/router';
import { AuthService } from '../../services/auth.service';

@Component({
  selector: 'app-verificacion',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './verificacion.component.html',
  styleUrls: ['./verificacion.component.css'],
})
export class VerificacionComponent implements OnInit {
  // Array de 6 inputs para el código
  codigo: string[] = ['', '', '', '', '', ''];
  email: string = '';
  cargando: boolean = false;
  error: string = '';
  éxito: string = '';

  constructor(
    private authService: AuthService,
    private router: Router
  ) {}

  ngOnInit(): void {
    // Obtener email del registro anterior
    const emailGuardado = sessionStorage.getItem('emailVerificacion');
    if (!emailGuardado) {
      this.router.navigate(['/registro']);
      return;
    }
    this.email = emailGuardado;
  }

  // Manejar cambios en los inputs
  onInputChange(index: number, valor: string): void {
    // Solo permitir números
    if (!/^\d*$/.test(valor)) {
      this.codigo[index] = '';
      return;
    }

    // Tomar solo el primer carácter
    if (valor.length > 1) {
      this.codigo[index] = valor.slice(0, 1);
    }

    // Moverse al siguiente input automáticamente
    if (valor.length === 1 && index < 5) {
      setTimeout(() => {
        const nextInput = document.getElementById(`digit-${index + 1}`) as HTMLInputElement;
        if (nextInput) {
          nextInput.focus();
        }
      }, 0);
    }
  }

  // Manejar tecla de retroceso para borrar
  onKeyDown(index: number, event: KeyboardEvent): void {
    if (event.key === 'Backspace') {
      if (this.codigo[index] === '' && index > 0) {
        // Si el input está vacío, ir al anterior
        const prevInput = document.getElementById(
          `digit-${index - 1}`
        ) as HTMLInputElement;
        if (prevInput) {
          prevInput.focus();
        }
      }
    }
  }

  // Enviar código de verificación
  verificar(): void {
    const codigoCompleto = this.codigo.join('');

    if (codigoCompleto.length !== 6) {
      this.error = 'Por favor completa los 6 dígitos';
      return;
    }

    this.cargando = true;
    this.error = '';

    this.authService.verificar(this.email, codigoCompleto).subscribe({
      next: (response) => {
        if (response.success) {
          this.éxito = response.message;

          // Redirigir a login después de 2 segundos
          setTimeout(() => {
            sessionStorage.removeItem('emailVerificacion');
            this.router.navigate(['/login']);
          }, 2000);
        } else {
          this.error = response.message;
        }
        this.cargando = false;
      },
      error: (err) => {
        this.error = err.error?.message || 'Error al verificar código';
        this.cargando = false;
      },
    });
  }

  // Reenviar código
  reenviar(): void {
    // Aquí irían lógica para reenviar el código
    this.éxito = 'Código reenviado a ' + this.email;
  }
}
<!-- Template HTML de Verificación -->

<div class="verificacion-container">
  <button class="btn-atras" onclick="window.history.back()">&larr; Atr&aacute;s</button>

  <div class="verificacion-contenedor">
    <!-- Icono -->
    <div class="icono-verificacion">&#9993;&#65039;</div>

    <h1>Verifica tu correo electr&oacute;nico</h1>

    <p class="subtitulo">
      Ingresa el codigo de 6 digitos que enviamos a <strong>{{ email }}</strong>
    </p>

    <!-- Mensaje de error -->
    <div *ngIf="error" class="alert alert-error">
      {{ error }}
    </div>

    <!-- Actualizado comentario para reflejar el nombre correcto de la variable -->
    <!-- Mensaje de exito -->
    <div *ngIf="exito" class="alert alert-success">
      {{ exito }}
    </div>

    <!-- Inputs para código -->
    <div class="codigo-inputs">
      <input
        *ngFor="let digit of codigo; let i = index"
        [id]="'digit-' + i"
        type="text"
        class="input-digito"
        maxlength="1"
        [(ngModel)]="codigo[i]"
        (input)="onInputChange(i, codigo[i])"
        (keydown)="onKeyDown(i, $event)"
      />
    </div>

    <!-- Botones -->
    <button
      class="btn btn-primary btn-bloque"
      (click)="verificar()"
      [disabled]="cargando"
    >
      {{ cargando ? 'Verificando...' : 'Verificar y continuar' }}
    </button>

    <!-- Link para reenviar -->
    <p class="texto-reenvio">
      &iquest;No recibiste el c&oacute;digo?
      <button class="btn-reenvio" (click)="reenviar()">Reenviar</button>
    </p>
  </div>
</div>
